import{_ as o,o as a,c as d,a5 as t}from"./chunks/framework.-jms6n7v.js";const p=JSON.parse('{"title":"Node.js 변경 기록","description":"Node.js 패키지 darudb의 변경 기록이며, 최신 기록이 위에 옵니다. 패키지마다 버전을 따로 매기고 기록도 따로 둡니다. 다른 언어 패키지의 기록은 사이드바에서 언어를 바꾸면 볼 수 있습니다. 변경 기록은 패키지와 함께 관리하며 영어로 작성하므로, 아래 항목은 원문…","frontmatter":{"title":"Node.js 변경 기록","order":1,"editLink":false,"outline":[2,3],"prev":{"text":"상수","link":"/ko/types/node/constants"},"next":{"text":"다른 DB와 비교","link":"/ko/compare"}},"headers":[{"level":2,"title":"Node.js 패키지 darudb","slug":"node-js-패키지-darudb","link":"#node-js-패키지-darudb","children":[{"level":3,"title":"darudb vNext (2026--)","slug":"darudb-vnext-2026","link":"#darudb-vnext-2026","children":[{"level":4,"title":"Changed","slug":"changed","link":"#changed","children":[]},{"level":4,"title":"Fixed","slug":"fixed","link":"#fixed","children":[]}]},{"level":3,"title":"darudb v1.1.0 (2026-10-09)","slug":"darudb-v1-1-0-2026-10-09","link":"#darudb-v1-1-0-2026-10-09","children":[{"level":4,"title":"Breaking changes","slug":"breaking-changes","link":"#breaking-changes","children":[]},{"level":4,"title":"Added","slug":"added","link":"#added","children":[]},{"level":4,"title":"Changed","slug":"changed-1","link":"#changed-1","children":[]},{"level":4,"title":"Fixed","slug":"fixed-1","link":"#fixed-1","children":[]}]},{"level":3,"title":"darudb v1.0.1 (2026-10-07)","slug":"darudb-v1-0-1-2026-10-07","link":"#darudb-v1-0-1-2026-10-07","children":[{"level":4,"title":"Fixed","slug":"fixed-2","link":"#fixed-2","children":[]}]},{"level":3,"title":"darudb v1.0.0 (2026-10-05)","slug":"darudb-v1-0-0-2026-10-05","link":"#darudb-v1-0-0-2026-10-05","children":[{"level":4,"title":"Added","slug":"added-1","link":"#added-1","children":[]}]}]}],"relativePath":"ko/changelog/node.md","filePath":"ko/changelog/node.md","lastUpdated":null}'),n={name:"ko/changelog/node.md"};function i(s,e,c,r,l,h){return a(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="node-js-변경-기록" tabindex="-1">Node.js 변경 기록 <a class="header-anchor" href="#node-js-변경-기록" aria-label="Permalink to &quot;Node.js 변경 기록&quot;">​</a></h1><p>Node.js 패키지 <code>darudb</code>의 변경 기록이며, 최신 기록이 위에 옵니다. 패키지마다 버전을 따로 매기고 기록도 따로 둡니다. 다른 언어 패키지의 기록은 사이드바에서 언어를 바꾸면 볼 수 있습니다. 변경 기록은 패키지와 함께 관리하며 영어로 작성하므로, 아래 항목은 원문 그대로입니다.</p><h2 id="node-js-패키지-darudb" tabindex="-1">Node.js 패키지 <code>darudb</code> <a class="header-anchor" href="#node-js-패키지-darudb" aria-label="Permalink to &quot;Node.js 패키지 `darudb`&quot;">​</a></h2><h3 id="darudb-vnext-2026" tabindex="-1">darudb vNext (2026--) <a class="header-anchor" href="#darudb-vnext-2026" aria-label="Permalink to &quot;darudb vNext (2026--)&quot;">​</a></h3><h4 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>A sync commit on Linux, Android and the BSDs makes the file durable with <code>fdatasync</code> rather than <code>fsync</code>, which leaves out the file&#39;s times and still syncs its length with its data. A sync commit of one object takes a quarter less time for it on a GitHub-hosted Linux runner, 312 µs against 413. macOS, iOS and Windows sync as before.</li><li>A commit asks the file system for the file&#39;s length only when its record counts pages past both the published commit&#39;s and the last one the commit wrote, rather than at every commit. A deferred commit of one object takes 11% less time for it on a GitHub-hosted Linux runner, 22.3 µs against 25.1.</li></ul><h4 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>backup</code> and <code>backupAsync</code> refuse a <code>passwordHashing</code> cost out of range with <code>INVALID_ARGUMENT</code> before they write anything, as opening does, whether a password is given or not. With a password they failed with <code>INTERNAL</code>, and without one they ignored the cost.</li></ul><h3 id="darudb-v1-1-0-2026-10-09" tabindex="-1">darudb v1.1.0 (2026-10-09) <a class="header-anchor" href="#darudb-v1-1-0-2026-10-09" aria-label="Permalink to &quot;darudb v1.1.0 (2026-10-09)&quot;">​</a></h3><h4 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h4><ul><li>The file format is version 6, <code>FORMAT_VERSION</code>, which earlier releases cannot open. Opening a file of version 5 raises it to version 6 while no other process has it open, so a file this release has opened no longer opens with 1.0, in Node.js or in any other language&#39;s package. An application that may go back to an earlier release, or that shares its file with a program still on one, opens with <code>upgradeFormat: false</code>, which also creates new files in version 5, and calls <code>upgradeFormat</code> once nothing older opens the file.</li></ul><h4 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>The <code>upgradeFormat</code> option of <code>open</code> and <code>openAsync</code>, and <code>upgradeFormat</code> and <code>upgradeFormatAsync</code>, which say whether opening raises a file of an older format version, and raise an open one.</li></ul><h4 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>An index whose entries for one value come in key order, as a non-unique index&#39;s do while the objects&#39; primary keys grow, fills its pages as it goes, where splitting a page in the middle left half of each empty, and so do the branches of every tree. A file of 400,000 sample objects with 14 indexes is 7% smaller for it. Keys in no particular order split pages evenly, as before.</li><li><code>compact</code> and <code>compactAsync</code> first write again, full, every tree whose pages inserts left part empty, so that the file ends about as small as a backup&#39;s copy: the same file compacts to 119 MiB rather than 140 MiB.</li><li>File format 6 writes the lengths in a leaf&#39;s entries as varints rather than in five bytes. A file of 400,000 sample objects with 14 indexes takes 8% fewer pages, 126 MiB against 138, and compacts to 110 MiB against 119, with reads and writes as fast as before. A file raised from version 5 has only its header rewritten; its leaves take the new layout as writes change them, and <code>compact</code> rewrites the trees where that saves room.</li><li>The native addon is built with its loops aligned to 64 bytes, so that where a hot loop lands no longer depends on the rest of the build: in a development build, the position of one loop alone made one-object deferred commits 15% slower. It is about 7% larger for it. The build for 64-bit Arm Windows is the exception, since the compiler cannot write that platform&#39;s unwind information for a function with padding inside it.</li></ul><h4 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>compact</code> and <code>compactAsync</code> no longer grow the file when a value in an overflow run near the file&#39;s end finds no run of free pages below to move into. The run stays where it is, and a round of moves that would grow the file is dropped.</li></ul><h3 id="darudb-v1-0-1-2026-10-07" tabindex="-1">darudb v1.0.1 (2026-10-07) <a class="header-anchor" href="#darudb-v1-0-1-2026-10-07" aria-label="Permalink to &quot;darudb v1.0.1 (2026-10-07)&quot;">​</a></h3><h4 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li>The copy of a key that <code>open</code>, <code>openAsync</code>, <code>salvage</code> and <code>backup</code> make on the way to the engine is kept in memory the package wipes, as <code>setKey</code> already did.</li></ul><h3 id="darudb-v1-0-0-2026-10-05" tabindex="-1">darudb v1.0.0 (2026-10-05) <a class="header-anchor" href="#darudb-v1-0-0-2026-10-05" aria-label="Permalink to &quot;darudb v1.0.0 (2026-10-05)&quot;">​</a></h3><h4 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>Database.open</code> opens a database file, creating it when nothing exists at the path, with <code>create</code> and <code>pageSize</code> options. <code>path</code>, <code>isOpen</code>, <code>pageSize</code> and <code>formatVersion</code> describe the open database, and <code>close</code> flushes and closes it.</li><li>Every error thrown by the package carries the engine&#39;s stable <code>code</code>, such as <code>NOT_FOUND</code>, <code>NOT_A_DATABASE</code> or <code>CLOSED</code>.</li><li>Several processes can open one database file at once, coordinated through the engine&#39;s file locks. A database on a network file system is refused with <code>UNSUPPORTED_FILE_SYSTEM</code>.</li><li><code>engineVersion()</code> and <code>FORMAT_VERSION</code> report the engine inside the package and the file format version it reads and writes.</li><li>Collections of objects under a schema declared with <code>t</code>, <code>collection</code> and <code>schema</code>, passed to <code>Database.open</code> as <code>schema</code>. TypeScript infers every object&#39;s type from the declaration. <code>db.read(fn)</code> and <code>db.write(fn)</code> run a function in a transaction, committing a write when the function returns and aborting it when it throws, with <code>durability: &#39;deferred&#39;</code> to commit without waiting for the disk. A collection offers <code>get</code>, <code>find</code>, <code>findOne</code>, <code>count</code>, <code>insert</code>, <code>insertMany</code>, <code>put</code>, <code>putMany</code> and <code>delete</code>, and objects cross into the engine as records, a batch in one call. A property the schema does not have is refused, and so is a modifier on a list&#39;s element, such as <code>t.list(t.string().index())</code>, rather than dropped: an index goes on the list itself. <code>t.bigint()</code> declares an int read as a <code>bigint</code>, write transactions on one file do not nest, even through two <code>Database</code> objects or from a migration function, and <code>busyTimeout</code> sets how long a write waits for another process.</li><li>Queries built with <code>where</code>, <code>sortBy</code>, <code>limit</code> and <code>offset</code>, typed by the collection&#39;s fields, or written in the query language with parameters. <code>conditions</code> and <code>Query</code> build filters outside a collection.</li><li>The <code>cacheSize</code> option of <code>Database.open</code> and <code>Database.openAsync</code> sets how much memory the page cache of a file may take, in bytes: 32 MiB by default.</li><li>Prepared queries: <code>db.prepare(collection, query)</code> parses a query once, as text or built with <code>param</code> in place of values, and <code>find</code>, <code>findOne</code> and <code>count</code> run it with its parameters&#39; values, in synchronous and asynchronous transactions. The package also keeps up to 256 texts it has parsed, so a text query run again with other parameters is not parsed again.</li><li>Migrations: raising the schema&#39;s version migrates the file when it opens, with the renames, deletions and replaced fields a migration lists and a JavaScript function that reads the objects as they were through <code>previous</code> and <code>previousKeys</code>.</li><li><code>db.schemaVersion</code>, and <code>db.sync()</code> to make deferred commits durable.</li><li>The package is written in TypeScript, and its type declarations are generated from its source. They name the types of <code>t</code>, <code>Database</code> and <code>Query</code> as <code>TypeBuilders</code>, <code>DatabaseOpener</code> and <code>QueryConstructor</code>.</li><li>An asynchronous API: <code>Database.openAsync</code>, <code>readAsync</code>, <code>writeAsync</code>, <code>syncAsync</code> and <code>closeAsync</code> do the engine&#39;s work on the libuv thread pool and resolve promises, so the event loop never waits for the disk or for another process&#39;s writer. Their transaction functions and migration functions may be asynchronous, every collection method returns a promise, and a transaction runs its operations in the order they were called and commits once they have all settled. Operations called together, or while earlier ones are on the pool, cross into the engine as one batch in one trip, and <code>readAsync</code> begins its read on the calling thread, since a read waits for no writer. This process&#39;s writes on one file queue in JavaScript rather than on the pool, however each handle named the file, a hard link on Windows included, <code>syncAsync</code> and <code>closeAsync</code> with them, and a synchronous <code>write</code>, <code>sync</code> or <code>close</code> while an asynchronous write holds the file fails with <code>INVALID_ARGUMENT</code> rather than blocking the event loop.</li><li><code>update(key, changes)</code> on the collections of synchronous and asynchronous write transactions sets the fields it is given, keeps the rest, and says whether there was an object. <code>null</code> makes an optional field null and gives a field with a default its default, and a field left <code>undefined</code> stays as it is. Only the changed fields cross into the engine, which changes the stored record where it lies, so updating a field costs less than reading the object and putting it back.</li><li><code>db.check()</code> and <code>db.checkAsync()</code>, the integrity check of the published commit, which report every problem they find, each with its page and its tree or collection, rather than throwing.</li><li><code>db.backup(path)</code> and <code>db.backupAsync(path)</code>, a copy of the published commit in a new file, which the same key or password opens and which never replaces a file already at the path. A <code>key</code> or a <code>password</code> in their <code>BackupOptions</code> encrypts the copy under a new data key instead, which is how a file&#39;s data key changes, and how a plain database&#39;s copy is encrypted.</li><li><code>db.compact()</code> and <code>db.compactAsync()</code>, which make the file smaller in place. Like a write, <code>compactAsync</code> waits its turn after this process&#39;s other writes on the file, and <code>compact</code> is refused while one of them holds it.</li><li><code>Database.salvage(from, into)</code> and <code>Database.salvageAsync(from, into)</code>, which rescue what they can of a damaged file into a new one, and report what they rescued and what they could not. They work on a file that does not open, need it alone, so a file in use fails with <code>BUSY</code>, and never replace a file already at <code>into</code>.</li><li>Encryption: <code>key</code> or <code>password</code> in the options of <code>open</code>, <code>openAsync</code> and <code>Database.salvage</code> encrypts a new database or opens an encrypted one, <code>passwordHashing</code> sets the cost of hashing a password, <code>db.isEncrypted</code> tells the two kinds of file apart, and <code>setKey</code>, <code>setPassword</code> and their <code>Async</code> twins change the key. Opening an encrypted database without its key fails with <code>KEY_REQUIRED</code>, and with another one with <code>WRONG_KEY</code>.</li><li>Electron&#39;s main process is supported, and the tests run the package there, in Electron 44. The guide says how several Electron processes share one file and how to keep the addon outside an <code>asar</code> archive.</li><li>The prebuilt addons ship as optional dependencies under the <code>@darudb</code> scope, one package per platform, such as <code>@darudb/darudb-linux-x64-gnu</code>, and npm installs only the one for the platform it runs on. Every platform package ships <code>LICENSE</code> and <code>THIRD_PARTY_NOTICES.txt</code>, the licences of the Rust crates and of the C source linked into its addon.</li></ul>',23)])])}const f=o(n,[["render",i]]);export{p as __pageData,f as default};
